sys_script_include.script:
var BOFA_SI_KafkaProducerV2 = Class.create();
BOFA_SI_KafkaProducerV2.prototype = {
    initialize: function() {
        /*
         * ProducerV2 signature:
         *
         * send(
         *     topicSysID,
         *     key,
         *     message,
         *     isSync,
         *     headers,
         *     schemaID
         * )
         */
        this.topicSysID = ""; // Param 1
        this.messageKey = ""; // Param 2
        this.messagePayload = ""; // Param 3
        this.asynchronousCall = false;
        // header is subject to discussion (optional)
        // schema ID is omitted for now. (optional)



    },

    /*
    Takes two parameter
    1. Payload for Kafka (JSON stringified)
    2. Object of the record
    */
    sendPayload: function(payload, gr) {
        try {

            var sourceTable = gr.getTableName().toString();
            if (sourceTable == "sn_vul_vulnerable_item" || sourceTable == "sn_vul_app_vulnerable_item" || sourceTable == "sn_vul_container_image_vulnerable_item" || sourceTable == "sn_vulc_result")
                this.topicSysID = gs.getProperty('x_boar_bofa_usem_1.x_boar_bofa.usem.kafka.topic_sys_id').toString(); // subject to change as per instance's topic
            else if (sourceTable == "sn_vul_app_vulnerability" || sourceTable == "sn_vul_container_vulnerability" || sourceTable == "sn_vul_vulnerability" || sourceTable == "sn_vulc_result_group")
                this.topicSysID = gs.getProperty('x_boar_bofa_usem_1.x_boar_bofa.usem.kafka.topic_sys_id').toString(); // keeping this as a placeholder. Topic is not yet created for remediation tasks in servicenow
            else {
                gs.error("BOFA_SI_KafkaProducerV2 has hit an error. Cannot find associated Kafka topic for the table - " + sourceTable);
                return false;
            }

            this.messageKey = sourceTable + "." + gr.getUniqueValue(); // table_backend_name.record_sys_id

            this.messagePayload = payload;

            var producer = new sn_ih_kafka.ProducerV2();
            var response = producer.send(this.topicSysID,
                this.messageKey,
                this.messagePayload,
                this.asynchronousCall,
                null,
                null,
            ); // sent to Kafa
        } catch (err) {
            gs.error("BOFA_SI_KafkaProducerV2 failed with error \n " + err);
        }
    },

    type: 'BOFA_SI_KafkaProducerV2'
};
